      pack_ultimate: 'അൾട്ടിമേറ്റ് പായ്ക്ക്',
      pack_ultimate_desc: 'പ്രോ ക്രിയേറ്റർമാർക്കും ഉള്ളടക്ക ടീമുകൾക്കും',
      credits_count: '{{count}} AI ക്രെഡിറ്റുകൾ',
      how_credits_used: 'AI ക്രെഡിറ്റുകൾ എങ്ങനെ ഉപയോഗിക്കുന്നു?',
      based_on_actual_cost: 'യഥാർത്ഥ AI ജനറേഷൻ ചെലവിനെ അടിസ്ഥാനമാക്കി (ഇമേജ് ~ ₹10, വീഡിയോ ~ ₹200)',
      usage_basic_image: 'ബേസിക് AI ഇമേജ്',
      usage_premium_image: 'പ്രീമിയം AI ഇമേജ്',
