      usage_video_std: 'AI വീഡിയോ (സ്റ്റാൻഡേർഡ്)',
      usage_video_prem: 'AI വീഡിയോ (പ്രീമിയം)',
      credits_range: '{{range}} ക്രെഡിറ്റുകൾ',
      instant_credit_update: 'തൽക്ഷണ ക്രെഡിറ്റ് അപ്‌ഡേറ്റ്',
